// Handwritten formulas from penquire's scans (Variable Compleja II, Curso Avanzado de Análisis, Stats Recap,
// Análisis Matemático), cut down to their ink: grey-level PNGs where white is pen. loadEq tints one to any colour.
const EQ = {
  empirical: { w: 559, h: 132, src: 'data:image/png;base64,' },
  gamma: { w: 623, h: 116, src: 'data:image/png;base64,' },
  gradient: { w: 176, h: 83, src: 'data:image/png;base64,' },
  lagrange: { w: 1044, h: 154, src: 'data:image/png;base64,' },
  mascheroni: { w: 711, h: 88, src: 'data:image/png;base64,' },
  product: { w: 459, h: 115, src: 'data:image/png;base64,' },
  projection: { w: 565, h: 133, src: 'data:image/png;base64,' },
  quotient: { w: 658, h: 156, src: 'data:image/png;base64,' },
  sine: { w: 464, h: 95, src: 'data:image/png;base64,' },
  zeta: { w: 561, h: 125, src: 'data:image/png;base64,' },
};
const loadEq = (name, rgb) => new Promise((done) => {
  const im = new Image();
  im.onload = () => {
    const c = document.createElement('canvas'); c.width = im.width; c.height = im.height;
    const x = c.getContext('2d'); x.drawImage(im, 0, 0);
    const d = x.getImageData(0, 0, c.width, c.height), p = d.data;
    for (let i = 0; i < p.length; i += 4) { p[i + 3] = p[i]; p[i] = rgb[0]; p[i + 1] = rgb[1]; p[i + 2] = rgb[2]; }
    x.putImageData(d, 0, 0); done(c);
  };
  im.src = EQ[name].src;
});
